#[test]
fn preview_upload_progress_reports_deferred_work() {
    assert!(!GpuUploadProgress::default().has_pending());
    assert!(GpuUploadProgress {
        pending_meshes: 1,
        ..GpuUploadProgress::default()
    }
    .has_pending());
    assert!(GpuUploadProgress {
        pending_textures: 1,
        ..GpuUploadProgress::default()
    }
    .has_pending());
}

#[test]
fn runtime_upload_budget_remains_unbounded_by_default() {
    let budget = GpuUploadBudget::default();
    assert_eq!(budget.max_mesh_uploads_per_frame, usize::MAX);
    assert_eq!(budget.max_texture_uploads_per_frame, usize::MAX);
}

